<?php $page_title='Semua Nilai'; require_once __DIR__.'/../includes/header.php'; require_login(['admin']); $rows=db()->query('SELECT m.npm,m.nama mahasiswa,mk.kode,mk.nama mata_kuliah,n.nilai_akhir,n.nilai_huruf,n.bobot FROM nilai n JOIN krs k ON k.id=n.id_krs JOIN mahasiswa m ON m.id=k.id_mahasiswa JOIN mata_kuliah mk ON mk.id=k.id_mk ORDER BY m.nama')->fetchAll(); ?><h3 class="mb-4">Semua Nilai</h3><div class="card p-4"><div class="table-responsive"><table class="table datatable"><thead><tr><th>NPM</th><th>Mahasiswa</th><th>Mata Kuliah</th><th>Nilai Akhir</th><th>Huruf</th><th>Bobot</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['npm'])?></td><td><?=e($r['mahasiswa'])?></td><td><?=e($r['kode'].' — '.$r['mata_kuliah'])?></td><td><?=number($r['nilai_akhir'])?></td><td><span class="badge text-bg-primary"><?=e($r['nilai_huruf'])?></span></td><td><?=number($r['bobot'])?></td></tr><?php endforeach?></tbody></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
